"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["79909"],{57226(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.documento_exigido.consequencia_incoerente_com_acao_da_vaga","status":422,"titulo":"A consequ\xeancia do descumprimento da exig\xeancia \xe9 incoerente com a a\xe7\xe3o declarada na modalidade que ela alcan\xe7a"},"descricao":{"codigo":"uniplus.selecao.documento_exigido.consequencia_incoerente_com_acao_da_vaga","requisitos":["UNI-REQ-0523"],"oQueAconteceu":["Quando uma modalidade de vaga declara o que acontece com o candidato indeferido (a a\xe7\xe3o de\\nindeferimento), a consequ\xeancia de indeferimento do documento exigido tem de ser a mesma. O\\ndocumento apontado declara uma consequ\xeancia diferente da a\xe7\xe3o de uma modalidade que ele pode\\nalcan\xe7ar.","A compara\xe7\xe3o considera as modalidades ofertadas que a exig\xeancia pode alcan\xe7ar pelas condi\xe7\xf5es\\ndela, e s\xf3 as que declaram a\xe7\xe3o de indeferimento. A consequ\xeancia da exig\xeancia e a a\xe7\xe3o da\\nmodalidade usam o mesmo c\xf3digo (`RETIRA_A_MODALIDADE`). A consequ\xeancia `RETIRA_O_ACRESCIMO` n\xe3o entra nesta compara\xe7\xe3o: ela retira s\xf3 o acr\xe9scimo, n\xe3o decide o destino da modalidade e pode ser declarada em qualquer exig\xeancia. A mensagem de detalhe indica o documento e a modalidade em conflito.","A confer\xeancia acontece quando a configura\xe7\xe3o vai ser congelada, na publica\xe7\xe3o ou na retifica\xe7\xe3o em ato \xfanico. Os documentos exigidos s\xe3o conferidos\\nprimeiro e, depois deles, os grupos de alternativas (OU) com consequ\xeancia pr\xf3pria (ver\\n[`uniplus.selecao.regra_de_comprovacao.consequencia_incoerente_com_acao_da_vaga`](/erros/uniplus.selecao.regra_de_comprovacao.consequencia_incoerente_com_acao_da_vaga)).\\nA confer\xeancia re\xfane todas as viola\xe7\xf5es encontradas, sem parar na primeira."],"comoResolver":["Alinhe a consequ\xeancia do documento \xe0 a\xe7\xe3o de indeferimento da modalidade apontada, ou revise\\na a\xe7\xe3o dessa modalidade, se for ela que est\xe1 errada. Depois, repita a opera\xe7\xe3o."],"ondeAparece":["Publica\xe7\xe3o inicial do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Documento exigido"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"e5dad467d85ce0f062b88f68241ad834bc540cf0"}}')}}]);